using System; using System.Data.Entity; using System.Linq; using System.Web.Mvc; using MyStoreCustomer.Models; using MyStoreCustomer.Services;
namespace MyStoreCustomer.Controllers {
 [Authorize] public class CustomerController:Controller { private StoreDbContext db=new StoreDbContext();
 [HttpGet] public ActionResult MyOrder(string status="all",string search="",int page=1){var c=db.Customers.FirstOrDefault(x=>x.Username==User.Identity.Name);if(c==null)return HttpNotFound();var q=db.Orders.Include(x=>x.OrderDetails.Select(d=>d.Product)).Where(x=>x.CustomerID==c.CustomerID);if(!String.IsNullOrWhiteSpace(search)){int id;if(Int32.TryParse(search.Trim(),out id))q=q.Where(x=>x.OrderID==id);else{string term=search.Trim();q=q.Where(x=>x.OrderDetails.Any(d=>d.Product.ProductName.Contains(term)));}}if(status!="all")q=q.Where(x=>x.Status==status);int count=q.Count();page=Math.Max(1,page);var m=new MyOrderViewModel{Search=search,Status=status,Page=page,PageSize=2,TotalCount=count,Orders=q.OrderByDescending(x=>x.OrderDate).ThenByDescending(x=>x.OrderID).Take(Math.Min(page*2,50)).ToList()};return View(m);}
 [HttpGet] public ActionResult OrderDetails(int id){var o=db.Orders.Include(x=>x.OrderDetails.Select(d=>d.Product)).FirstOrDefault(x=>x.OrderID==id&&x.Customer.Username==User.Identity.Name);if(o==null)return HttpNotFound();return View(o);}
 [HttpPost,ValidateAntiForgeryToken] public ActionResult BuyAgain(int productId){var p=db.Products.Find(productId);if(p==null)return HttpNotFound();CartService.AddOne(Session,p);TempData["Message"]="Đã thêm sản phẩm vào giỏ hàng.";return RedirectToAction("MyOrder");}
 protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);} } }